/**
 * Seed catalog for loovi_ds — name, Figma nodeId, AI-READY description and
 * accessibility of every component in the seed, so Widgetbook stories and
 * widget docs never copy text by hand. Also writes the Flutter inventory
 * (phase 3 list: what is implemented, what enters the app, what stays out).
 *
 * Usage: node packages/flutter_ds/tool/generate_catalog.mjs   (or npm run flutter:catalog)
 * Output (do not edit by hand):
 *   lib/src/generated/seed_catalog.g.dart
 *   ../../FLUTTER-INVENTORY.md
 */
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const PKG = path.resolve(__dirname, '..');
const ROOT = path.resolve(PKG, '../..');
const seed = JSON.parse(fs.readFileSync(path.join(ROOT, 'design-system-tokens.storybook.updated.v2.json'), 'utf8'));
const C = seed.storybook.components;
const S2_FILE_KEY = seed.meta.fileKey || 'mHm12Zu9tgNmaSYnooihE5';

/** Phase 2 wave (implemented in Flutter, mode app-cliente). Keep in sync with lib/loovi_ds.dart. */
const WAVE = JSON.parse(fs.readFileSync(path.join(__dirname, 'wave.json'), 'utf8'));
const missing = WAVE.filter((n) => !C[n]);
if (missing.length) throw new Error(`Onda cita componente fora do seed: ${missing.join(', ')}`);

/** Not for the customer app (backoffice / desktop / web chrome). Judgment call, reviewable. */
const NOT_APP = new Set([
  'SystemHeader', 'OrganizationHeader', 'NavigationRailExpanded', 'NavigationRailExpandedTree',
  'NavigationRailExpandedItem', 'NavigationRailCompact', 'NavigationRailCompactItem', 'NavigationDrawer',
  'NavigationDrawerItem', 'Breadcrumb', 'BreadcrumbItem', 'Table', 'TableRow', 'TableCell',
  'TableExpandCell', 'TableSkeleton', 'Pagination', 'PaginationItem', 'PaginationSelectMenu',
  'PaginationSelectMenuItem', 'PaginationSelectInput', 'CommentItem', 'Keyboard', 'SearchViewModal',
  'DividerVertical', 'Calendar', 'CalendarDay', 'CalendarPeriodNav',
]);

const dartStr = (s) => `'${String(s ?? '').replace(/\\/g, '\\\\').replace(/'/g, "\\'").replace(/\$/g, '\\$').replace(/\n/g, '\\n')}'`;
const flat = (v) => (v == null ? '' : typeof v === 'string' ? v : JSON.stringify(v));

const L = [
  '// GENERATED by packages/flutter_ds/tool/generate_catalog.mjs — do not edit by hand.',
  `// Seed revision ${seed.meta.storybookRevision}`,
  '',
  '/// Seed metadata for one DS component (Figma nodeId, AI-READY description).',
  'class LooviSeedComponent {',
  `  const LooviSeedComponent({required this.name, required this.nodeId, required this.description, required this.accessibility, required this.variants, this.fileKey = ${dartStr(S2_FILE_KEY)}});`,
  '  final String name;',
  '  /// Figma node id (file [fileKey]; [DS] 2.0 - S2 unless the seed names another library).',
  '  final String nodeId;',
  '  final String description;',
  '  /// Seed `accessibility` block, flattened.',
  '  final String accessibility;',
  '  /// Seed `variants` block, flattened (JSON).',
  '  final String variants;',
  '  /// Figma file key that holds [nodeId] (seed `figmaFileKey`, default S2).',
  '  final String fileKey;',
  '  /// Figma URL of the component set.',
  "  String get figmaUrl => 'https://www.figma.com/design/$fileKey?node-id=${nodeId.replaceAll(':', '-')}';",
  '}',
  '',
  '/// Every component in the seed, by name.',
  'abstract final class LooviSeedCatalog {',
  `  static const String revision = ${dartStr(seed.meta.storybookRevision)};`,
  '  static const Map<String, LooviSeedComponent> components = {',
];
for (const [name, c] of Object.entries(C)) {
  L.push(`    ${dartStr(name)}: LooviSeedComponent(name: ${dartStr(name)}, nodeId: ${dartStr(c.nodeId)}, description: ${dartStr(c.description)}, accessibility: ${dartStr(flat(c.accessibility))}, variants: ${dartStr(flat(c.variants))}${c.figmaFileKey && c.figmaFileKey !== S2_FILE_KEY ? `, fileKey: ${dartStr(c.figmaFileKey)}` : ''}),`);
}
L.push('  };');
L.push('  /// Lookup that fails loudly if a widget names a component missing from the seed.');
L.push('  static LooviSeedComponent of(String name) => components[name] ?? (throw ArgumentError(\'$name not in seed\'));');
L.push('}');
fs.mkdirSync(path.join(PKG, 'lib/src/generated'), { recursive: true });
fs.writeFileSync(path.join(PKG, 'lib/src/generated/seed_catalog.g.dart'), L.join('\n') + '\n', 'utf8');

// ---- inventory ----
const rows = Object.entries(C).map(([name, c]) => {
  const flutter = WAVE.includes(name) ? '✅ onda 1' : '—';
  const app = NOT_APP.has(name) ? 'não (web/backoffice)' : 'sim';
  return `| ${name} | \`${c.nodeId}\` | ${c.reactImplemented ? 'sim' : 'não'} | ${flutter} | ${app} |`;
});
const md = [
  '# Inventário Flutter — DS S2',
  '',
  `> Gerado por \`packages/flutter_ds/tool/generate_catalog.mjs\` (seed \`${seed.meta.storybookRevision}\`). Não editar à mão.`,
  '> "Entra no app" é uma triagem inicial para o App Cliente; revisar antes de cada nova onda.',
  '',
  `Total: ${rows.length} componentes · Flutter: ${WAVE.length} · fora do app: ${[...NOT_APP].filter((n) => C[n]).length}`,
  '',
  '| Componente | nodeId | React | Flutter | Entra no app |',
  '| --- | --- | --- | --- | --- |',
  ...rows,
  '',
];
fs.writeFileSync(path.join(ROOT, 'FLUTTER-INVENTORY.md'), md.join('\n'), 'utf8');
console.log(`loovi_ds catalog: ${rows.length} components · wave ${WAVE.length}`);
